def get_valid_input(prompt):
    """Get a valid input from the user."""
    while True:
        try:
            user_input = input(prompt)
            tokens = user_input.split()
            if len(tokens) == 2 and tokens[0].isdigit() and tokens[1] in ['+', '-', '*', '/']:
                return int(tokens[0]), tokens[1]
            else:
                print("Invalid input. Please enter a number followed by an operation ('+', '-', '*', or '/').")
        except ValueError:
            print("Invalid input. Please enter a number.")

def perform_operation(num1, op, num2):
    """Perform the given operation on the two numbers."""
    if op == '+':
        return num1 + num2
    elif op == '-':
        return num1 - num2
    elif op == '*':
        return num1 * num2
    elif op == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2
    else:
        raise ValueError("Invalid operation. Please use '+' for addition, '-' for subtraction, '*' for multiplication, or '/' for division.")

while True:
    try:
        num1, op = get_valid_input("Enter the first number: ")
        num2 = int(input("Enter the second number: "))

        result = perform_operation(num1, op, num2)
        print(f"{num1} {op} {num2} = {result}")

    except ValueError as e:
        print(e)
    except ZeroDivisionError:
        print("Cannot divide by zero.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        break
